// Companion cases for the Material Balance Studio videos, on the Ekene kit's
// conventions (oilfield units, psia, dates on the 1st, Bo, Rs, Bg and Bw on
// every row so the case carries its own PVT, as the kit's tank history does).
// Ekene itself is an undersaturated oil with no gas cap and no aquifer; these
// two cases are labelled scenarios, generated by the canonical MBAL engine
// from stated truth, so the studio can be checked against a known answer:
//
//  1. ekene-gascap-scenario-history.csv: an oil rim saturated at discovery
//     with a gas cap (m stated) and a Carter-Tracy edge aquifer (stated). The
//     pressures are the engine's forward simulation (simulatePressureHistory)
//     of the stated tank on the stated production; the row PVT is the engine's
//     own correlation table at each pressure. A Havlena-Odeh run with the
//     stated m and aquifer returns the stated N.
//  2. oboro-gas-scenario-history.csv: a dry gas reservoir in the Oboro Sand
//     (the kit's logs show it gas-bearing), volumetric (no aquifer): Z and Bg
//     from the engine's correlations; p/z is a straight line to the stated G.
//
// Truth and the contact geometry for the Contacts tab go to *-truth.json.
//   esbuild --bundle --platform=node --format=esm tools/demo-video/seed/mbal_companions.mjs --outfile=/tmp/c.mjs
//   node /tmp/c.mjs [outDir]
import fs from 'node:fs';
import path from 'node:path';
import {
  simulatePressureHistory, computeMaterialBalance, generatePvtTable,
} from '../../../packages/engines/engines/mbal/mbalEngine.ts';

const out = process.argv[2] || '/root/demo-video-work/mbal-assets';
const CORR = { pb_rs_bo: 'standing', oil_viscosity: 'beggs_robinson', z_factor: 'hall_yarborough', water: 'mccain', gas_viscosity: 'lee_gonzalez_eakin' };
const DAY = 86400000;
const dateAdd = (iso, months) => { const d = new Date(`${iso}T00:00:00Z`); d.setUTCMonth(d.getUTCMonth() + months); return d.toISOString().slice(0, 10); };
const days = (a, b) => (new Date(`${b}T00:00:00Z`) - new Date(`${a}T00:00:00Z`)) / DAY;

/** The engine's own PVT at one pressure (a two-step table bracketing it). */
function pvtAt(base, p) {
  const t = generatePvtTable({
    fluid_system: base.fluid_system, oil_gravity_api: base.oil_gravity_api, gas_specific_gravity: base.gas_specific_gravity,
    reservoir_temperature_f: base.reservoir_temperature_f, bubble_point_psia: base.bubble_point_psia, initial_pressure_psia: base.initial_pressure_psia,
    pvt_correlations: CORR, pressure_min_psia: p, pressure_max_psia: p + 1e-6, n_steps: 2,
  });
  return t.rows[0];
}

function writeCsv(file, header, rows) {
  fs.writeFileSync(file, `${[header.join(','), ...rows.map((r) => r.join(','))].join('\n')}\n`);
}

// ---- 1. Ekene gas-cap scenario ---------------------------------------------
export const GASCAP = {
  name: 'Ekene gas-cap scenario',
  N_stb: 18e6, m: 0.45,
  inputs: {
    fluid_system: 'oil_with_gas_cap', has_gas_cap: true, has_aquifer: true,
    initial_pressure_psia: 3200, bubble_point_psia: 3200, reservoir_temperature_f: 180,
    initial_water_saturation: 0.25, oil_gravity_api: 32, gas_specific_gravity: 0.75, water_salinity_ppm: 35000,
    formation_compressibility_psi: 4e-6, water_compressibility_psi: 3e-6,
    aquifer_model: 'carter_tracy',
    aquifer_params: {
      aquifer_radius_ft: 2400, radius_ratio: 6, aquifer_thickness_ft: 60, aquifer_permeability_md: 150,
      aquifer_porosity: 0.22, aquifer_water_viscosity_cp: 0.45, theta_degrees: 180, aquifer_total_compressibility_psi: 7e-6,
    },
    pvt_source: 'correlated', pvt_correlations: CORR,
  },
  start: '2017-01-01', steps: 16, stepMonths: 6,
  // oil rate, producing GOR and water cut by year since first oil
  qo: (yr) => 2800 * Math.exp(-0.10 * yr),
  gor: (yr, rsi) => rsi * (1 + 0.22 * yr),
  wcut: (yr) => Math.max(0, Math.min(0.45, 0.09 * (yr - 2))),
  contacts: { initial_goc_ft: 4950, initial_owc_ft: 5060, area_goc_acres: 200, area_owc_acres: 180, porosity: 0.22, sor_water: 0.25, sor_gas: 0.15 },
};

function gascap() {
  const g = GASCAP;
  const rsi = pvtAt(g.inputs, g.inputs.initial_pressure_psia).Rs;
  const rows = [{ timestep_index: 0, observation_date: g.start, pressure_psia: g.inputs.initial_pressure_psia, cum_oil_stb: 0, cum_gas_scf: 0, cum_water_stb: 0 }];
  let np = 0; let gp = 0; let wp = 0; let prev = g.start;
  for (let k = 1; k <= g.steps; k++) {
    const date = dateAdd(g.start, k * g.stepMonths);
    const dt = days(prev, date);
    const yrMid = (days(g.start, prev) + dt / 2) / 365.25;
    const qo = g.qo(yrMid);
    const dNp = qo * dt;
    np += dNp; gp += dNp * g.gor(yrMid, rsi);
    const fw = g.wcut(yrMid); wp += dNp * fw / (1 - fw);
    rows.push({ timestep_index: k, observation_date: date, pressure_psia: g.inputs.initial_pressure_psia, cum_oil_stb: np, cum_gas_scf: gp, cum_water_stb: wp });
    prev = date;
  }
  const inputs = { ...g.inputs, gas_cap_ratio_m: g.m, production_data: rows };
  const notes = new Set();
  const p = simulatePressureHistory(inputs, g.N_stb, notes);
  const withP = rows.map((r, i) => {
    const v = pvtAt(g.inputs, p[i]);
    return { ...r, pressure_psia: p[i], bo_rb_stb: v.Bo, rs_scf_stb: v.Rs, bg_rb_mscf: v.Bg, bw_rb_stb: v.Bw };
  });
  // round as written, then check the engine on the rounded rows
  const r = (v, n) => Number(v.toFixed(n));
  const written = withP.map((x) => ({
    ...x, pressure_psia: r(x.pressure_psia, 4), cum_oil_stb: r(x.cum_oil_stb, 2), cum_gas_scf: r(x.cum_gas_scf, 0), cum_water_stb: r(x.cum_water_stb, 2),
    bo_rb_stb: r(x.bo_rb_stb, 9), rs_scf_stb: r(x.rs_scf_stb, 6), bg_rb_mscf: r(x.bg_rb_mscf, 9), bw_rb_stb: r(x.bw_rb_stb, 9),
  }));
  const check = computeMaterialBalance({ ...inputs, production_data: written });
  return { rows: written, check, notes: [...notes], rsi };
}

// ---- 2. Oboro gas scenario ---------------------------------------------------
export const OBORO = {
  name: 'Oboro gas scenario',
  G_scf: 60e9,
  inputs: {
    fluid_system: 'gas', has_gas_cap: false, has_aquifer: false,
    initial_pressure_psia: 4350, reservoir_temperature_f: 205, initial_water_saturation: 0.22,
    gas_specific_gravity: 0.65, water_salinity_ppm: 35000,
    formation_compressibility_psi: 4e-6, water_compressibility_psi: 3e-6,
    aquifer_model: 'none', pvt_source: 'correlated', pvt_correlations: CORR,
  },
  start: '2019-01-01', steps: 12, stepMonths: 6,
  qg: (yr) => 22e6 * Math.exp(-0.06 * yr), // scf/d
  wgr: 2.0, // stb per MMscf
};

function oboro() {
  const g = OBORO;
  const rows = [{ timestep_index: 0, observation_date: g.start, pressure_psia: g.inputs.initial_pressure_psia, cum_oil_stb: 0, cum_gas_scf: 0, cum_water_stb: 0 }];
  let gp = 0; let prev = g.start;
  for (let k = 1; k <= g.steps; k++) {
    const date = dateAdd(g.start, k * g.stepMonths);
    const dt = days(prev, date);
    const yrMid = (days(g.start, prev) + dt / 2) / 365.25;
    gp += g.qg(yrMid) * dt;
    rows.push({ timestep_index: k, observation_date: date, pressure_psia: g.inputs.initial_pressure_psia, cum_oil_stb: 0, cum_gas_scf: gp, cum_water_stb: gp / 1e6 * g.wgr });
    prev = date;
  }
  const inputs = { ...g.inputs, production_data: rows };
  const p = simulatePressureHistory(inputs, g.G_scf, new Set());
  const r = (v, n) => Number(v.toFixed(n));
  const written = rows.map((x, i) => {
    const v = pvtAt(g.inputs, p[i]);
    return { ...x, pressure_psia: r(p[i], 4), cum_gas_scf: r(x.cum_gas_scf, 0), cum_water_stb: r(x.cum_water_stb, 2), z_factor: r(v.z, 9), bg_rb_mscf: r(v.Bg, 9), bw_rb_stb: r(v.Bw, 9) };
  });
  const check = computeMaterialBalance({ ...inputs, production_data: written });
  return { rows: written, check };
}

fs.mkdirSync(out, { recursive: true });
const a = gascap();
writeCsv(path.join(out, 'ekene-gascap-scenario-history.csv'),
  ['date', 'pressure_psia', 'cum_oil_stb', 'cum_gas_scf', 'cum_water_stb', 'bo_rb_stb', 'rs_scf_stb', 'bg_rb_mscf', 'bw_rb_stb'],
  a.rows.map((x) => [x.observation_date, x.pressure_psia, x.cum_oil_stb, x.cum_gas_scf, x.cum_water_stb, x.bo_rb_stb, x.rs_scf_stb, x.bg_rb_mscf, x.bw_rb_stb]));
fs.writeFileSync(path.join(out, 'ekene-gascap-scenario-truth.json'), `${JSON.stringify({
  name: GASCAP.name, note: 'Scenario generated by the canonical MBAL engine from the stated truth (tools/demo-video/seed/mbal_companions.mjs). Ekene itself has no gas cap and no aquifer.',
  truth: { N_stb: GASCAP.N_stb, gas_cap_ratio_m: GASCAP.m, aquifer: GASCAP.inputs.aquifer_params, aquifer_model: 'carter_tracy' },
  case: { fluid_system: 'oil_with_gas_cap', initial_pressure_psia: 3200, bubble_point_psia: 3200, reservoir_temperature_f: 180, initial_water_saturation: 0.25, oil_gravity_api: 32, gas_specific_gravity: 0.75, water_salinity_ppm: 35000, cf_per_psi: 4e-6, cw_per_psi: 3e-6, rsi_scf_stb: a.rsi },
  contacts: GASCAP.contacts,
  engine_check: { ooip_stb: a.check.estimated_ooip_stb, r_squared: a.check.r_squared, final_ddi: a.check.final_ddi, final_gdi: a.check.final_gdi, final_wdi: a.check.final_wdi, final_cdi: a.check.final_cdi, we_rb_last: a.check.per_timestep?.at(-1)?.We_rb, warnings: a.check.warnings },
  simulator_notes: a.notes,
}, null, 2)}\n`);
const b = oboro();
writeCsv(path.join(out, 'oboro-gas-scenario-history.csv'),
  ['date', 'pressure_psia', 'cum_gas_scf', 'cum_water_stb', 'z_factor', 'bg_rb_mscf', 'bw_rb_stb'],
  b.rows.map((x) => [x.observation_date, x.pressure_psia, x.cum_gas_scf, x.cum_water_stb, x.z_factor, x.bg_rb_mscf, x.bw_rb_stb]));
fs.writeFileSync(path.join(out, 'oboro-gas-scenario-truth.json'), `${JSON.stringify({
  name: OBORO.name, note: 'Scenario generated by the canonical MBAL engine from the stated truth (tools/demo-video/seed/mbal_companions.mjs).',
  truth: { G_scf: OBORO.G_scf, aquifer_model: 'none' },
  case: { fluid_system: 'gas', initial_pressure_psia: OBORO.inputs.initial_pressure_psia, reservoir_temperature_f: OBORO.inputs.reservoir_temperature_f, initial_water_saturation: OBORO.inputs.initial_water_saturation, gas_specific_gravity: 0.65, water_salinity_ppm: 35000, cf_per_psi: 4e-6, cw_per_psi: 3e-6 },
  engine_check: { ogip_scf: b.check.estimated_ogip_scf, r_squared: b.check.r_squared, warnings: b.check.warnings },
}, null, 2)}\n`);
console.log('gas cap: N', a.check.estimated_ooip_stb, 'r2', a.check.r_squared, 'p', a.rows.map((x) => Math.round(x.pressure_psia)).join(' '));
console.log('  Np', Math.round(a.rows.at(-1).cum_oil_stb), 'Rp', Math.round(a.rows.at(-1).cum_gas_scf / a.rows.at(-1).cum_oil_stb), 'rsi', a.rsi, 'We', a.check.per_timestep?.at(-1)?.We_rb, 'idx', a.check.final_ddi, a.check.final_gdi, a.check.final_wdi, a.check.final_cdi, a.notes, a.check.warnings);
const lastT = a.check.per_timestep.at(-1); const lr = a.rows.at(-1); const C = GASCAP.contacts;
const dOwc = 5.615 * (lastT.We_rb - lr.cum_water_stb * lr.bw_rb_stb) / (C.area_owc_acres * 43560 * C.porosity * (1 - 0.25 - C.sor_water));
const dGoc = 5.615 * GASCAP.m * a.check.estimated_ooip_stb * lastT.Eg_rb_stb / (C.area_goc_acres * 43560 * C.porosity * (1 - 0.25 - C.sor_gas));
console.log('contacts: We', lastT.We_rb, 'WpBw', lr.cum_water_stb * lr.bw_rb_stb, 'dOWC ft', dOwc, 'dGOC ft', dGoc, 'RF', lr.cum_oil_stb / GASCAP.N_stb);
console.log('gas: G', b.check.estimated_ogip_scf, 'r2', b.check.r_squared, 'p', b.rows.map((x) => Math.round(x.pressure_psia)).join(' '), b.check.warnings);
